      "path": "src/client/index.ts",
      "content": "/**
 * dsh-douyin browser half: a sidebar video-feed panel.
 *
 * Mounting is dual-mode, mirroring dsh-browser-panel's compatibility pattern:
 *  - when the `betterSidebar` service is present (dsh-better-sidebar
 *    installed), the panel registers itself as a sidebar tab via its official
 *    registerTab protocol;
 *  - otherwise it falls back to a self-drawn right dock with a floating
 *    toggle button, so the plugin works with zero extra dependencies.
 *
 * The source list is data-driven (`VideoSource[]`): built-in defaults plus
 * user-added custom sources, persisted in localStorage. Swapping feeds later
 * (a new aggregator site, a different embed URL) means adding an entry —
 * no code changes. The shape is kept deliberately small so it can later be
 * promoted to host settings (settings namespace + RPC) without a UI rewrite.
 */
import { createElement, useCallback, useEffect, useMemo, useRef, useState } from 'react'
import ChevronLeft from 'lucide-react/dist/esm/icons/chevron-left.js'
import ChevronRight from 'lucide-react/dist/esm/icons/chevron-right.js'
import PanelRightClose from 'lucide-react/dist/esm/icons/panel-right-close.js'
import PanelRightOpen from 'lucide-react/dist/esm/icons/panel-right-open.js'
import Play from 'lucide-react/dist/esm/icons/play.js'
import { createRoot, type Root } from 'react-dom/client'
import type { ClientContext } from '@deepseek-ai/dsh-client-runtime/client'
import { DEFAULT_SOURCES, type SourceKind, type VideoSource } from '../feed-sources.ts'
import { MediaPlayer } from './MediaPlayer.ts'

export { DEFAULT_SOURCES }
export type { SourceKind, VideoSource }

/** Plugin id == bundle registration key. */
export const ID = 'dsh-douyin'

const STYLE_TAG_ID = `${ID}/styles`
const PREFS_KEY = `${ID}:prefs`

/** Old persisted entries (v0.1, no kind) default to iframe mode. */
const LEGACY_KIND: SourceKind = 'web'

/** Persisted panel prefs: active source + user-added sources. */
export interface FeedPrefs {
  activeSourceId: string
  customSources: VideoSource[]
}

export const EMPTY_PREFS: FeedPrefs = { activeSourceId: DEFAULT_SOURCES[0]!.id, customSources: [] }

/** Display labels for the three source modes (add-form radio + tab tooltip). */
export const KIND_LABEL: Record<SourceKind, string> = {
  feed: '随机流',
  direct: '单视频',
  web: '网页',
}

export function readPrefs(): FeedPrefs {
  try {
    const raw = localStorage.getItem(PREFS_KEY)
    if (!raw) return EMPTY_PREFS
    const parsed = JSON.parse(raw) as Partial<FeedPrefs>
    const customSources = Array.isArray(parsed.customSources)
      ? (parsed.customSources as VideoSource[]).filter(s => s && typeof s.id === 'string' && typeof s.name === 'string' && typeof s.url === 'string')
        .map(s => ({ ...s, kind: s.kind ?? LEGACY_KIND }))
      : []
    const candidates = [...DEFAULT_SOURCES, ...customSources]
    const activeSourceId = typeof parsed.activeSourceId === 'string' && candidates.some(s => s.id === parsed.activeSourceId)
      ? parsed.activeSourceId
      : EMPTY_PREFS.activeSourceId
    return { activeSourceId, customSources }
  } catch {
    return EMPTY_PREFS
  }
}

export function writePrefs(prefs: FeedPrefs): void {
  try {
    localStorage.setItem(PREFS_KEY, JSON.stringify(prefs))
  } catch {
    // storage unavailable — prefs just won't persist
  }
}

/** All sources, built-ins first, then customs. */
export function allSources(prefs: FeedPrefs): VideoSource[] {
  return [...DEFAULT_SOURCES, ...prefs.customSources]
}

/** No hard inject: services are probed optionally at apply time. */
export const inject: string[] = []

