/* ------------------------------------------------------------------ */
/* Panel component: compact series selector + immersive player.        */
/* ------------------------------------------------------------------ */

function FeedPanel(): React.ReactElement {
  const [prefs, setPrefs] = useState<FeedPrefs>(readPrefs)
  const sources = useMemo(() => allSources(prefs), [prefs])
  const activeIndex = Math.max(0, sources.findIndex(s => s.id === prefs.activeSourceId))
  const active = sources[activeIndex]
  const [centeredIndex, setCenteredIndex] = useState(activeIndex)
  const trackRef = useRef<HTMLDivElement>(null)
  const rootRef = useRef<HTMLDivElement>(null)
  const focusIndexRef = useRef<number | null>(null)
  const settleTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null)
  const programmaticIndexRef = useRef<number | null>(null)

  useEffect(() => { writePrefs(prefs) }, [prefs])

  const scrollToIndex = useCallback((index: number, behavior: ScrollBehavior): void => {
    const track = trackRef.current
    const item = track?.children.item(index) as HTMLElement | null
    if (track === null || item === null || track.clientWidth === 0) return
    const trackRect = track.getBoundingClientRect()
    const itemRect = item.getBoundingClientRect()
    const left = track.scrollLeft
      + itemRect.left + itemRect.width / 2
      - trackRect.left - trackRect.width / 2
    track.scrollTo({ left, behavior })
  }, [])

  const clearSettleTimer = useCallback((): void => {
    if (settleTimerRef.current === null) return
    clearTimeout(settleTimerRef.current)
    settleTimerRef.current = null
  }, [])

  const activateIndex = useCallback((index: number, behavior: ScrollBehavior = 'smooth'): void => {
    const nextIndex = Math.max(0, Math.min(sources.length - 1, index))
    const source = sources[nextIndex]
    if (source === undefined) return
    clearSettleTimer()
    programmaticIndexRef.current = nextIndex
    setCenteredIndex(nextIndex)
    scrollToIndex(nextIndex, behavior)
    setPrefs(current => current.activeSourceId === source.id
      ? current
      : { ...current, activeSourceId: source.id })
    if (focusIndexRef.current === nextIndex) {
      requestAnimationFrame(() => {
        const item = trackRef.current?.children.item(nextIndex) as HTMLElement | null
        item?.focus({ preventScroll: true })
        focusIndexRef.current = null
      })
    }
  }, [clearSettleTimer, scrollToIndex, sources])

  // Center persisted selections after mount and after a hidden dock opens.
  useEffect(() => {
    const track = trackRef.current
    if (track === null) return
    const center = (): void => {
      if (programmaticIndexRef.current !== null) return
      setCenteredIndex(activeIndex)
      scrollToIndex(activeIndex, 'auto')
    }
    center()
    const observer = new ResizeObserver(() => center())
    observer.observe(track)
    return () => observer.disconnect()
  }, [activeIndex, scrollToIndex])

  useEffect(() => () => clearSettleTimer(), [clearSettleTimer])

  const nearestToCenter = useCallback((): number => {
    const track = trackRef.current
    if (track === null) return activeIndex
    const trackRect = track.getBoundingClientRect()
    const center = trackRect.left + trackRect.width / 2
    let nearest = activeIndex
    let nearestDistance = Number.POSITIVE_INFINITY
    Array.from(track.children).forEach((node, index) => {
      const itemRect = (node as HTMLElement).getBoundingClientRect()
      const distance = Math.abs(itemRect.left + itemRect.width / 2 - center)
      if (distance < nearestDistance) {
        nearest = index
        nearestDistance = distance
      }
    })
    return nearest
  }, [activeIndex])

  const handleTrackScroll = useCallback((): void => {
    const nextIndex = nearestToCenter()
    setCenteredIndex(nextIndex)
    clearSettleTimer()
    settleTimerRef.current = setTimeout(() => {
      const programmaticIndex = programmaticIndexRef.current
      if (programmaticIndex !== null) {
        programmaticIndexRef.current = null
        setCenteredIndex(programmaticIndex)
        scrollToIndex(programmaticIndex, 'auto')
        return
      }
      const source = sources[nextIndex]
      if (source !== undefined) {
        setPrefs(current => current.activeSourceId === source.id
          ? current
          : { ...current, activeSourceId: source.id })
      }
    }, 160)
  }, [clearSettleTimer, nearestToCenter, scrollToIndex, sources])

  const beginManualScroll = useCallback((): void => {
    programmaticIndexRef.current = null
    clearSettleTimer()
  }, [clearSettleTimer])

  const handleTrackWheel = useCallback((event: React.WheelEvent<HTMLDivElement>): void => {
    const distance = Math.abs(event.deltaX) > Math.abs(event.deltaY) ? event.deltaX : event.deltaY
    if (distance === 0) return
    event.preventDefault()
    beginManualScroll()
    event.currentTarget.scrollBy({ left: distance, behavior: 'auto' })
  }, [beginManualScroll])

  const handleTrackKey = useCallback((event: React.KeyboardEvent<HTMLDivElement>): void => {
    const focused = (event.target as HTMLElement).closest('.vf-series-item')
    const focusedIndex = focused === null || trackRef.current === null
      ? activeIndex
      : Array.from(trackRef.current.children).indexOf(focused)
    let nextIndex: number | null = null
    if (event.key === 'ArrowLeft') nextIndex = focusedIndex - 1
    else if (event.key === 'ArrowRight') nextIndex = focusedIndex + 1
    else if (event.key === 'Home') nextIndex = 0
    else if (event.key === 'End') nextIndex = sources.length - 1
    if (nextIndex === null) return
    event.preventDefault()
    focusIndexRef.current = Math.max(0, Math.min(sources.length - 1, nextIndex))
    activateIndex(nextIndex)
  }, [activateIndex, activeIndex, sources.length])

  /** Series bar floats above the video; wheel gestures outside the track
   * are forwarded to the player so top-of-video flicks still switch clips. */
  const forwardWheelToPlayer = useCallback((event: React.WheelEvent<HTMLElement>): void => {
    if ((event.target as HTMLElement).closest('.vf-series-track') !== null) return
    const player = rootRef.current?.querySelector('.vf-player')
    if (player === null || player === undefined) return
    player.dispatchEvent(new WheelEvent('wheel', {
      deltaY: event.deltaY,
      deltaX: event.deltaX,
      bubbles: true,
      cancelable: true,
    }))
  }, [])

  return createElement('div', { className: 'vf-root', ref: rootRef },
    createElement('nav', { className: 'vf-series-bar', 'aria-label': '视频系列', onWheel: forwardWheelToPlayer },
      createElement('div', { className: 'vf-series-nav' },
        createElement('button', {
          className: 'vf-series-arrow',
          type: 'button',
          title: '上一个系列',
          'aria-label': '上一个系列',
          disabled: centeredIndex === 0,
          onClick: () => activateIndex(centeredIndex - 1),
        }, createElement(ChevronLeft, { size: 17, strokeWidth: 2.4, 'aria-hidden': true })),
        createElement('div', {
          className: 'vf-series-track',
          ref: trackRef,
          role: 'tablist',
          'aria-label': '系列列表',
          onScroll: handleTrackScroll,
          onWheel: handleTrackWheel,
          onTouchStart: beginManualScroll,
          onKeyDown: handleTrackKey,
        },
          ...sources.map((source, index) => createElement('button', {
            key: source.id,
            className: 'vf-series-item',
            type: 'button',
            role: 'tab',
            title: source.name,
            'aria-selected': source.id === active.id,
            tabIndex: index === activeIndex ? 0 : -1,
            'data-distance': Math.min(Math.abs(index - centeredIndex), 3),
            onClick: () => activateIndex(index),
          }, source.name)),
        ),
        createElement('button', {
          className: 'vf-series-arrow',
          type: 'button',
          title: '下一个系列',
          'aria-label': '下一个系列',
          disabled: centeredIndex === sources.length - 1,
          onClick: () => activateIndex(centeredIndex + 1),
        }, createElement(ChevronRight, { size: 17, strokeWidth: 2.4, 'aria-hidden': true })),
      ),
    ),
    createElement('div', { className: 'vf-stage' },
      active.kind === 'web'
        ? createElement('iframe', { key: active.id, src: active.url, allow: 'autoplay; fullscreen; picture-in-picture' })
        : createElement(MediaPlayer, { key: active.id, source: active }),
    ),
  )
}

/* ------------------------------------------------------------------ */
/* Mounting: sidebar tab (better-sidebar) or fallback dock.            */
/* ------------------------------------------------------------------ */

/** DSH main content mount; compressed while the fallback dock is open. */
const MAIN_ROOT_SELECTOR = '#root'

/** Must stay in sync with the dock width expression in the stylesheet. */
const DOCK_WIDTH_CSS = 'min(100vw, clamp(380px, calc(100vh * 9 / 16), 700px))'

function setMainRootMargin(value: string): void {
  const root = document.querySelector(MAIN_ROOT_SELECTOR) as HTMLElement | null
  if (root !== null) root.style.marginRight = value
}

export function apply(ctx: ClientContext): void {
  ctx.effect(() => {
    const tag = document.createElement('style')
    tag.dataset.plugin = ID
    tag.dataset.pluginCss = STYLE_TAG_ID
    tag.textContent = css
    document.head.appendChild(tag)
    return () => { tag.remove() }
  }, `${ID}: styles`)

  const betterSidebar = ctx.get('betterSidebar') as { registerTab?: (descriptor: unknown) => () => void } | undefined

  if (betterSidebar?.registerTab) {
    ctx.effect(() => betterSidebar.registerTab!({
      id: 'dsh-douyin:feed',
      title: '刷视频',
      icon: (size: number) => createElement(Play, { size, strokeWidth: 2.2, 'aria-hidden': true }),
      single: true,
      component: () => createElement(FeedPanel),
