        ? createElement('div', { className: 'vf-dock' }, createElement(FeedPanel))
        : null,
    ))
  }
  render(false)

  ctx.effect(() => {
    return () => {
      root?.unmount()
      dockHost.remove()
      if (marginBeforeOpen !== null) setMainRootMargin(marginBeforeOpen)
    }
  }, `${ID}: dock lifecycle`)
}
